import React, { useState, useEffect } from 'react';
import { socialAPI } from '../services/api';
import '../styles/App.css';

const Social = () => {
  const [friends, setFriends] = useState([]);
  const [allUsers, setAllUsers] = useState([]);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [selectedFriend, setSelectedFriend] = useState(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('friends');
  const [profileData, setProfileData] = useState({
    name: '',
    bio: '',
    interests: [],
    collegeName: '',
  });
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchFriends();
  }, []);

  const fetchFriends = async () => {
    try {
      setLoading(true);
      const [friendsRes, profileRes] = await Promise.all([
        socialAPI.getFriends(),
        userAPI.getProfile(),
      ]);
      setFriends(friendsRes.data.friends);
      setProfileData({
        name: profileRes.data.user.name || '',
        bio: profileRes.data.user.bio || '',
        interests: profileRes.data.user.interests || [],
        collegeName: profileRes.data.user.collegeName || '',
      });
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedFriend) return;

    try {
      await socialAPI.sendMessage({
        recipientId: selectedFriend._id,
        content: newMessage,
      });
      setNewMessage('');
      fetchMessages(selectedFriend._id);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const fetchMessages = async (userId) => {
    try {
      const response = await socialAPI.getMessages(userId);
      setMessages(response.data.messages);
    } catch (error) {
      console.error('Error fetching messages:', error);
    }
  };

  const selectFriend = (friend) => {
    setSelectedFriend(friend);
    fetchMessages(friend._id);
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    try {
      await userAPI.updateProfile(profileData);
      alert('Profile updated successfully!');
      fetchFriends(); // Refresh data
    } catch (error) {
      console.error('Error updating profile:', error);
      alert('Error updating profile');
    }
  };

  const searchUsers = async () => {
    if (!searchQuery.trim()) return;
    try {
      const response = await userAPI.searchUsers(searchQuery);
      setAllUsers(response.data.users);
    } catch (error) {
      console.error('Error searching users:', error);
    }
  };

  const addFriend = async (friendId) => {
    try {
      await socialAPI.addFriend(friendId);
      alert('Friend request sent!');
      fetchFriends();
    } catch (error) {
      console.error('Error adding friend:', error);
    }
  };

  return (
    <div className="container">
      <h1>🤝 Social Hub</h1>

      <div className="grid" style={{ gridTemplateColumns: '300px 1fr' }}>
        {/* Friends List */}
        <div className="card">
          <h2>Friends ({friends.length})</h2>
          {loading ? (
            <div className="spinner"></div>
          ) : (
            <div>
              {friends.length === 0 ? (
                <p>No friends yet. Add friends to get started!</p>
              ) : (
                <ul style={{ listStyle: 'none' }}>
                  {friends.map((friend) => (
                    <li
                      key={friend._id}
                      onClick={() => selectFriend(friend)}
                      style={{
                        padding: '0.75rem',
                        cursor: 'pointer',
                        borderRadius: '4px',
                        marginBottom: '0.5rem',
                        backgroundColor: selectedFriend?._id === friend._id ? '#f0f4ff' : 'transparent',
                      }}
                    >
                      <strong>{friend.name}</strong>
                      <p style={{ fontSize: '0.85rem', color: '#666' }}>{friend.email}</p>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          )}
        </div>

        {/* Messages */}
        <div className="card">
          {selectedFriend ? (
            <>
              <h2>Chat with {selectedFriend.name}</h2>

              <div
                style={{
                  backgroundColor: '#f7f7f7',
                  borderRadius: '4px',
                  padding: '1rem',
                  minHeight: '400px',
                  maxHeight: '400px',
                  overflowY: 'auto',
                  marginBottom: '1rem',
                }}
              >
                {messages.map((msg) => (
                  <div
                    key={msg._id}
                    style={{
                      marginBottom: '1rem',
                      textAlign: msg.senderId === selectedFriend._id ? 'left' : 'right',
                    }}
                  >
                    <div
                      style={{
                        display: 'inline-block',
                        backgroundColor: msg.senderId === selectedFriend._id ? 'white' : '#667eea',
                        color: msg.senderId === selectedFriend._id ? 'black' : 'white',
                        padding: '0.75rem 1rem',
                        borderRadius: '8px',
                        maxWidth: '70%',
                      }}
                    >
                      {msg.content}
                    </div>
                  </div>
                ))}
              </div>

              <form onSubmit={sendMessage}>
                <div className="form-group">
                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Type a message..."
                  />
                </div>
                <button type="submit" className="btn btn-primary">
                  Send Message
                </button>
              </form>
            </>
          ) : (
            <p>Select a friend to start chatting</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Social;
